# found in the LICENSE file.

distros=(
"gs://chromeos-mirror/gentoo/distfiles/*"
"gs://chromeos-localmirror/distfiles"
)

check_package() {
    archive="$1"
    uri="$2"
    # Test if package is available in the distros
    for distro in "${distros[@]}"; do
        if [[ $(gsutil ls "${distro}/${archive}" | grep -c "${archive}") -ne 0 ]]; then
            printf "\nFound archive %s in distro %s\n" "${archive}" "${distro}"
            return
        fi
    done
    # Add variable name to list of sources to upload
    printf "\nPackage does not exist in predefined distro mirrors, uploading\n"
    curl -L -O "${uri}/${archive}"
    gsutil cp -n -a public-read "${archive}" "gs://chromeos-localmirror/distfiles/${archive}"
}

coreboot_package_version_names=(
"GMP"
"MPFR"
"MPC"
"GCC"
"BINUTILS"
"IASL"
)

coreboot_package_variable_types=(
"Version"
"Archive"
"Base_URL"
)

coreboot_package_variable_keep_types=(
"Version"
)

myhelp() {
    echo "Usage: $0 [-h|--help] [-d|--diff] [BUILDGCC_PATH [ECLASS_PATH]]"
    echo
    echo "Options:"
	echo "    [-h|--help]           This help"
	echo "    [-d|--diff]           Don't regenerate, just verify the file is correct"
    echo "    [BUILDGCC_PATH]       The path to coreboot/util/crossgcc/buildgcc"
    echo "    [ECLASS_PATH]         The path to eclass/coreboot-sdk-versions.eclass"
}
args=$(getopt -l diff,help -o dh -- "$@")
getopt_ret=$?
eval set -- "${args}"
if [ "${getopt_ret}" != 0 ]; then
	myhelp
	exit 1
fi

diff=0

while true ; do
        case "$1" in
        -h|--help)		shift; myhelp; exit 0;;
        -d|--diff)		shift; diff=1;;
        --)		shift; break;;
        *)		break;;
    esac
done

if [ $# -gt 2 ]; then
    echo "Excessive arguments: $*"
    myhelp
    exit 1
fi

BUILDGCC_PATH=${1:-"${HOME}/chromiumos/src/third_party/coreboot/util/crossgcc/buildgcc"}
ECLASS_PATH=${2:-"${HOME}/chromiumos/src/third_party/chromiumos-overlay/eclass/coreboot-sdk-versions.eclass"}

if [ "${diff}" != 0 ]; then
    DIFF_PATH="${ECLASS_PATH}"
    ECLASS_PATH="/tmp/coreboot-sdk-versions.eclass"
fi

# shellcheck disable=SC2016
echo -n '# Copyright 2025 The ChromiumOS Authors
# Use of this source code is governed by a BSD-style license that can be
# found in the LICENSE file.

# @ECLASS: coreboot-sdk-version.eclass
# @BLURB: Common version definition for coreboot-sdk compilers
# @DESCRIPTION:
# coreboot-sdk has a bootstrap compiler and builds for multiple architectures.
# This eclass has a common definition for toolchain versions pulled from the
# coreboot buildgcc script.

# THIS FILE IS AUTOGENERATED, DO NOT MODIFY

if [[ -z "${_ECLASS_COREBOOT_VERSION_SDK}" ]]; then
_ECLASS_COREBOOT_VERSION_SDK=1

# Check for EAPI 7+.
case "${EAPI:-0}" in
[0123456]) die "unsupported EAPI (${EAPI}) in eclass (${ECLASS})" ;;
esac

' > "${ECLASS_PATH}"

declare -A archives=()
declare -A uris=()

for package in "${coreboot_package_version_names[@]}"; do
    declare -A coreboot_package_versions
    for variable_type_name in "${coreboot_package_variable_types[@]}"; do
        variable_type=$(echo "${variable_type_name}" | tr '[:lower:]' '[:upper:]')
        found_variable="$(sed -n "s/^${package}_${variable_type}=\(.*\)/\1/p" "${BUILDGCC_PATH}")"
        # Strip trailing whitespace and comments
        found_variable=$(echo "${found_variable}" | awk '{print $1}')
        # Strip leading/trailing quotes if they exist
        package_version=$(echo "${found_variable}" | tr -d '"' )
        # Store found value for use later
        coreboot_package_versions[${variable_type}]=${package_version}
        # Add desired values to generated eclass
        for coreboot_package_variable_keep_type in "${coreboot_package_variable_keep_types[@]}"; do
            if [[ "${coreboot_package_variable_keep_type}" == "${variable_type_name}" ]]; then
                # shellcheck disable=SC2129
                printf "# @ECLASS-VARIABLE: %s_%s\n" "${package}" "${variable_type}" >> "${ECLASS_PATH}"
                printf "# @DESCRIPTION:\n" >> "${ECLASS_PATH}"
                printf "#   %s to be used for the %s package.\n" "${variable_type_name}" "${package}" >> "${ECLASS_PATH}"
                printf "export %s_%s=\"%s\"\n\n" "${package}" "${variable_type}" "${package_version}" >> "${ECLASS_PATH}"
                break
            fi
        done
    done
    # shellcheck disable=SC2129
    printf "# @ECLASS-VARIABLE: %s_SRC_URI\n" "${package}" >> "${ECLASS_PATH}"
    printf "# @DESCRIPTION:\n" >> "${ECLASS_PATH}"
    printf "#   SRC_URI to be used for the %s package.\n" "${package}" >> "${ECLASS_PATH}"
    printf "export %s_SRC_URI=\"%s/%s\"\n\n" "${package}" "${coreboot_package_versions['BASE_URL']}" "${coreboot_package_versions['ARCHIVE']}" >> "${ECLASS_PATH}"

    uris["${package}"]="${coreboot_package_versions['BASE_URL']//\$\{${package}_VERSION\}/${coreboot_package_versions['VERSION']}}"
    archives["${package}"]="${coreboot_package_versions['ARCHIVE']//\$\{${package}_VERSION\}/${coreboot_package_versions['VERSION']}}"
done

printf "fi\n" >> "${ECLASS_PATH}"

if [ "${diff}" != 0 ]; then
    if ! cmp "${DIFF_PATH}" "${ECLASS_PATH}" ; then
        echo
        echo "${DIFF_PATH} needs regenerated. Run these commands to fix:"
        echo "cros_sdk --enter"
        echo "cd ~/chromiumos/src/third_party/chromiumos-overlay"
        echo "./eclass/gen/coreboot_sdk_versions.sh"
        echo "for x in cross-embedded-*/coreboot-sdk*/*-9999.ebuild dev-embedded/coreboot-sdk-*/*-9999.ebuild; do"
        echo "  ebuild \$x manifest; done"
        exit 1
    fi
    exit 0
fi

for package in "${coreboot_package_version_names[@]}"; do
    echo "Checking package ${package} ${archives["${package}"]} ${uris["${package}"]}"
    check_package "${archives["${package}"]}" "${uris["${package}"]}" &
    PIDS+=($!)
done

for pid in "${PIDS[@]}"; do
  wait "${pid}"
done
